    core_.bindOutput(op, out);
    routineBindings_[op] = {.inputParams  = {cellA, cellB, dim, dir},
                            .outputParams = {out}};
    exportSymbol(mod, "link", op);
  }

  // delete: cell -> cell
  {
    CellRef cell = core_.arena().makeCell();
