struct AllocationStats {
  std::size_t calls{};
  std::size_t totalBytes{};
  std::size_t liveBytes{};
  std::size_t peakBytes{};
};

template <class T> struct CountingAllocator {
  using value_type = T;
  static inline AllocationStats stats{};
  CountingAllocator() noexcept = default;
  template <class U> CountingAllocator(const CountingAllocator<U> &) noexcept {}
  [[nodiscard]] T *allocate(std::size_t count) {
    const auto bytes = count * sizeof(T);
    auto *memory     = std::allocator<T>{}.allocate(count);
    ++stats.calls;
    stats.totalBytes += bytes;
    stats.liveBytes += bytes;
    stats.peakBytes = std::max(stats.peakBytes, stats.liveBytes);
    return memory;
  }
  void deallocate(T *memory, std::size_t count) noexcept {
    stats.liveBytes -= count * sizeof(T);
    std::allocator<T>{}.deallocate(memory, count);
  }
  template <class U>
  bool operator==(const CountingAllocator<U> &) const noexcept {
    return true;
  }
};

using Cell    = zigzag::CellRef;
using Alloc   = CountingAllocator<Cell>;
using Vector  = std::vector<Cell, Alloc>;
using Inline4 = zigzag::vortex::BasicOperandList<Alloc, 4>;
using Inline8 = zigzag::vortex::BasicOperandList<Alloc, 8>;

void resetStats() { Alloc::stats = {}; }
Cell inputAt(std::size_t index) { return static_cast<Cell>(17U + 31U * index); }
Cell rewriteSlot(Cell value) { return value ^ 0x5a5a5a5aU; }
std::uint64_t checksum(std::span<Cell> values) {
  std::uint64_t sum = 0;
  for (std::size_t i = 0; i < values.size(); ++i) {
    values[i] = rewriteSlot(values[i]);
    sum += static_cast<std::uint64_t>(values[i]) * (i + 1U);
  }
  return sum;
}

template <class Container> Container makeOwned(std::size_t arity) {
  Container result;
  for (std::size_t i = 0; i < arity; ++i) result.push_back(inputAt(i));
  return result;
}

struct CallerSpan {
  std::array<Cell, 8> inlineValues{};
  Vector spill;
  std::span<Cell> fill(std::size_t arity) {
    if (arity <= inlineValues.size()) {
      for (std::size_t i = 0; i < arity; ++i) inlineValues[i] = inputAt(i);
      return {inlineValues.data(), arity};
    }
    spill.clear();
    spill.reserve(arity);
    for (std::size_t i = 0; i < arity; ++i) spill.push_back(inputAt(i));
    return spill;
  }
  [[nodiscard]] std::size_t capacity() const noexcept {
    return spill.empty() ? inlineValues.size() : spill.capacity();
  }
};

std::uint64_t visitAndRewrite(std::size_t arity) {
  std::uint64_t sum = 0;
  for (std::size_t i = 0; i < arity; ++i)
    sum += static_cast<std::uint64_t>(rewriteSlot(inputAt(i))) * (i + 1U);
  return sum;
}

template <class Container>
void reportOwned(std::string_view name, std::size_t arity,
                 std::size_t objectBytes) {
  resetStats();
  auto values       = makeOwned<Container>(arity); // includes by-value return
  const auto result = checksum(values.span());
  const auto stats  = Alloc::stats;
  std::cout << "layout," << name << ',' << arity << ',' << objectBytes << ','
            << values.capacity() << ',' << stats.calls << ','
            << stats.totalBytes << ',' << stats.liveBytes << ','
            << stats.peakBytes << ',' << result << '\n';
}

template <class Container>
void reportVectorLike(std::string_view name, std::size_t arity) {
  resetStats();
  auto values       = makeOwned<Container>(arity);
  const auto result = checksum(std::span<Cell>{values.data(), values.size()});
  const auto stats  = Alloc::stats;
  std::cout << "layout," << name << ',' << arity << ',' << sizeof(Container)
            << ',' << values.capacity() << ',' << stats.calls << ','
            << stats.totalBytes << ',' << stats.liveBytes << ','
            << stats.peakBytes << ',' << result << '\n';
}

template <class Container> std::span<Cell> view(Container &container) {
  return {container.data(), container.size()};
}

template <class Container>
void reportCopyMove(std::string_view name, std::size_t arity) {
  resetStats();
  auto original         = makeOwned<Container>(arity);
  const auto beforeCopy = Alloc::stats;
  auto copied           = original;
  const auto afterCopy  = Alloc::stats;
  auto moved            = std::move(copied);
  const auto afterMove  = Alloc::stats;
  std::cout << "copy-move," << name << ',' << arity << ','
            << (afterCopy.calls - beforeCopy.calls) << ','
            << (afterCopy.totalBytes - beforeCopy.totalBytes) << ','
            << (afterMove.calls - afterCopy.calls) << ','
            << (afterMove.totalBytes - afterCopy.totalBytes) << ','
            << checksum(view(moved)) << '\n';
}

void reportSpan(std::size_t arity) {
  resetStats();
  CallerSpan caller;
  auto values       = caller.fill(arity);
  const auto result = checksum(values);
  const auto stats  = Alloc::stats;
  std::cout << "layout,caller-span," << arity << ',' << sizeof(CallerSpan)
            << ',' << caller.capacity() << ',' << stats.calls << ','
            << stats.totalBytes << ',' << stats.liveBytes << ','
            << stats.peakBytes << ',' << result << '\n';
}

void reportVisitor(std::size_t arity) {
  resetStats();
  const auto result = visitAndRewrite(arity);
  const auto stats  = Alloc::stats;
  std::cout << "layout,visitor," << arity << ",0,0," << stats.calls << ','
            << stats.totalBytes << ',' << stats.liveBytes << ','
            << stats.peakBytes << ',' << result << '\n';
}

} // namespace

int main() {
  std::cout << "kind,representation,arity,object_bytes,capacity,alloc_calls,"
               "requested_bytes,live_bytes,peak_bytes,checksum\n";
  for (const std::size_t arity : {0U, 1U, 2U, 4U, 8U, 9U, 64U, 1024U}) {
    reportVectorLike<Vector>("vector-return", arity);
    reportOwned<Inline4>("inline4", arity, sizeof(Inline4));
    reportOwned<Inline8>("inline8", arity, sizeof(Inline8));
    reportSpan(arity);
    reportVisitor(arity);
  }
  std::cout
      << "kind,representation,arity,copy_alloc_calls,copy_requested_bytes,"
         "move_alloc_calls,move_requested_bytes,checksum\n";
  for (const std::size_t arity : {0U, 1U, 2U, 4U, 8U, 9U, 64U, 1024U}) {
    reportCopyMove<Vector>("vector-return", arity);
    reportCopyMove<Inline4>("inline4", arity);
    reportCopyMove<Inline8>("inline8", arity);
  }
}

#include "common/xanadu/vortex/operand_list.hpp"

#include <algorithm>
#include <array>
#include <atomic>
#include <charconv>
#include <chrono>
#include <cstddef>
#include <cstdint>
#include <iostream>
#include <memory>
#include <span>
#include <string_view>
#include <vector>

namespace {

using Cell    = zigzag::CellRef;
using Vector  = std::vector<Cell>;
using Inline4 = zigzag::vortex::BasicOperandList<std::allocator<Cell>, 4>;
using Inline8 = zigzag::vortex::BasicOperandList<std::allocator<Cell>, 8>;

Cell inputAt(std::size_t index, std::uint64_t seed) {
  return static_cast<Cell>(17U + 31U * index + seed * 13U);
}
Cell rewriteSlot(Cell value, std::uint64_t seed) {
  return value ^ static_cast<Cell>(0x5a5a5a5aU + seed * 3U);
}
template <class Container> std::span<Cell> view(Container &container) {
  return {container.data(), container.size()};
}
std::uint64_t mutateAndChecksum(std::span<Cell> values, std::uint64_t seed) {
  std::uint64_t sum = 0;
  for (std::size_t i = 0; i < values.size(); ++i) {
    values[i] = rewriteSlot(values[i], seed);
    sum += static_cast<std::uint64_t>(values[i]) * (i + 1U);
  }
  return sum;
}

template <class Container>
Container makeOwned(std::size_t arity, std::uint64_t seed) {
  Container result;
  for (std::size_t i = 0; i < arity; ++i) result.push_back(inputAt(i, seed));
  return result;
}

struct CallerSpan {
  std::array<Cell, 8> inlineValues{};
  Vector spill;
  std::span<Cell> fill(std::size_t arity, std::uint64_t seed) {
    if (arity <= inlineValues.size()) {
      for (std::size_t i = 0; i < arity; ++i)
        inlineValues[i] = inputAt(i, seed);
      return {inlineValues.data(), arity};
    }
    spill.clear();
    spill.reserve(arity);
    for (std::size_t i = 0; i < arity; ++i) spill.push_back(inputAt(i, seed));
    return spill;
  }
};

std::uint64_t visitAndRewrite(std::size_t arity, std::uint64_t seed) {
  std::uint64_t sum = 0;
  for (std::size_t i = 0; i < arity; ++i)
    sum += static_cast<std::uint64_t>(rewriteSlot(inputAt(i, seed), seed)) *
           (i + 1U);
  return sum;
}

template <class Run>
void timeLoop(std::string_view phase, std::string_view representation,
              std::size_t arity, std::size_t iterations, Run &&run) {
  std::uint64_t sink = 0;
  const auto start   = std::chrono::steady_clock::now();
  for (std::size_t i = 0; i < iterations; ++i) {
    const auto seed = static_cast<std::uint64_t>(i + 1U);
    sink += run(seed);
    std::atomic_signal_fence(std::memory_order_seq_cst);
  }
  const auto elapsed = std::chrono::duration_cast<std::chrono::nanoseconds>(
                           std::chrono::steady_clock::now() - start)
                           .count();
  std::cout << phase << ',' << representation << ',' << iterations << ','
            << arity << ',' << elapsed << ',' << sink << '\n';
}

template <class Container>
void timeCopy(std::string_view name, std::size_t arity,
              std::size_t iterations) {
  const auto source = makeOwned<Container>(arity, 19U);
  timeLoop("copy", name, arity, iterations, [&](std::uint64_t seed) {
    auto copied = source;
    return mutateAndChecksum(view(copied), seed);
  });
}

template <class Container>
void timeMove(std::string_view name, std::size_t arity,
              std::size_t iterations) {
  std::vector<Container> sources;
  sources.reserve(iterations);
  for (std::size_t i = 0; i < iterations; ++i)
    sources.push_back(makeOwned<Container>(arity, i + 19U));
  std::size_t index = 0;
  timeLoop("move", name, arity, iterations, [&](std::uint64_t seed) {
    auto moved = std::move(sources[index++]);
    return mutateAndChecksum(view(moved), seed);
  });
}

std::size_t parseIterations(int argc, char **argv) {
  constexpr std::size_t defaultIterations = 10'000U;
  if (argc == 1) return defaultIterations;
  if (argc != 3 || std::string_view(argv[1]) != "--iterations") return 0;
  const std::string_view text{argv[2]};
  std::size_t value = 0;
  const auto [end, error] =
      std::from_chars(text.data(), text.data() + text.size(), value);
  if (error != std::errc{} || end != text.data() + text.size() || value == 0)
    return 0;
  return value;
}

} // namespace

int main(int argc, char **argv) {
  const auto iterations = parseIterations(argc, argv);
  if (iterations == 0) {
    std::cerr << "usage: operand_timing_primary [--iterations N]\n";
    return 2;
  }
  std::cout << "phase,representation,iterations,arity,elapsed_ns,checksum\n";
  for (const std::size_t arity : {0U, 1U, 2U, 4U, 8U, 9U, 64U, 1024U}) {
    timeLoop("build-return-mutate", "vector-return", arity, iterations,
             [&](std::uint64_t seed) {
               auto result = makeOwned<Vector>(arity, seed);
               return mutateAndChecksum(view(result), seed);
             });
    timeLoop("build-return-mutate", "inline4", arity, iterations,
             [&](std::uint64_t seed) {
               auto result = makeOwned<Inline4>(arity, seed);
               return mutateAndChecksum(view(result), seed);
             });
    timeLoop("build-return-mutate", "inline8", arity, iterations,
             [&](std::uint64_t seed) {
               auto result = makeOwned<Inline8>(arity, seed);
               return mutateAndChecksum(view(result), seed);
             });
    timeLoop("build-span-mutate", "caller-span", arity, iterations,
             [&](std::uint64_t seed) {
               CallerSpan owner;
               return mutateAndChecksum(owner.fill(arity, seed), seed);
             });
    timeLoop("visit-direct", "visitor", arity, iterations,
             [&](std::uint64_t seed) { return visitAndRewrite(arity, seed); });
    timeCopy<Vector>("vector-return", arity, iterations);
    timeCopy<Inline4>("inline4", arity, iterations);
    timeCopy<Inline8>("inline8", arity, iterations);
    timeMove<Vector>("vector-return", arity, iterations);
    timeMove<Inline4>("inline4", arity, iterations);
    timeMove<Inline8>("inline8", arity, iterations);
  }
}

#include <gtest/gtest.h>

#include <cstddef>
#include <cstdint>
#include <memory>
#include <new>
#include <ranges>
#include <type_traits>
#include <vector>

#include "common/xanadu/vortex/operand_list.hpp"

namespace {

template <class T> struct FailingAllocator {
  using value_type                      = T;
  static inline bool failNextAllocation = false;

  FailingAllocator() noexcept = default;
  template <class U> FailingAllocator(const FailingAllocator<U> &) noexcept {}

  [[nodiscard]] T *allocate(const std::size_t count) {
    if (failNextAllocation) {
      failNextAllocation = false;
      throw std::bad_alloc{};
    }
    return std::allocator<T>{}.allocate(count);
  }

  void deallocate(T *memory, const std::size_t count) noexcept {
    std::allocator<T>{}.deallocate(memory, count);
  }

  template <class U>
  bool operator==(const FailingAllocator<U> &) const noexcept {
    return true;
  }
};

using TestOperandList =
    zigzag::vortex::BasicOperandList<FailingAllocator<zigzag::CellRef>>;
static_assert(std::ranges::contiguous_range<zigzag::vortex::OperandList>);
static_assert(std::ranges::sized_range<zigzag::vortex::OperandList>);

TEST(OperandListTest, SupportsInlineBoundarySpillAndLargeWings) {
  for (const std::size_t count : {0U, 8U, 9U, 1024U}) {
    zigzag::vortex::OperandList operands;
    for (std::size_t i = 0; i < count; ++i)
      operands.push_back(static_cast<zigzag::CellRef>(i + 10));

    ASSERT_EQ(operands.size(), count);
    EXPECT_EQ(operands.empty(), count == 0);
    for (std::size_t i = 0; i < count; ++i) EXPECT_EQ(operands[i], i + 10);
    if (count != 0) {
      EXPECT_EQ(operands.front(), 10U);
      EXPECT_EQ(operands.back(), count + 9U);
    }
    auto view = operands.span();
    EXPECT_EQ(view.size(), count);
    if (count > 1) {
      view[1] = 777;
      EXPECT_EQ(operands[1], 777U);
    }
  }
}

TEST(OperandListTest, CopyAndMovePreserveBothRepresentationsAndSourceValidity) {
  zigzag::vortex::OperandList inlineValues;
  for (zigzag::CellRef value = 0; value < 8; ++value)
    inlineValues.push_back(value);
  auto inlineCopy = inlineValues;
  EXPECT_EQ(inlineCopy, inlineValues);
  auto inlineMove = std::move(inlineCopy);
  EXPECT_EQ(inlineMove, inlineValues);
  EXPECT_TRUE(inlineCopy.empty());
  inlineCopy.push_back(81);
  EXPECT_EQ(inlineCopy.front(), 81U);

  zigzag::vortex::OperandList spilledValues;
  for (zigzag::CellRef value = 0; value < 64; ++value)
    spilledValues.push_back(value + 100);
  auto spilledCopy = spilledValues;
  EXPECT_EQ(spilledCopy, spilledValues);
  auto spilledMove = std::move(spilledCopy);
  EXPECT_EQ(spilledMove, spilledValues);
  EXPECT_TRUE(spilledCopy.empty());
  spilledCopy.push_back(999);
  EXPECT_EQ(spilledCopy.front(), 999U);

  inlineMove = spilledValues;
  EXPECT_EQ(inlineMove, spilledValues);
  inlineMove = std::move(inlineCopy);
  ASSERT_EQ(inlineMove.size(), 1U);
  EXPECT_EQ(inlineMove.front(), 81U);
  EXPECT_TRUE(inlineCopy.empty());
}

TEST(OperandListTest, SpilledCopyAssignmentFailurePreservesInlineDestination) {
  TestOperandList source;
  for (std::uint32_t value = 0; value < 12; ++value)
    source.push_back(value + 100);

  TestOperandList destination;
  destination.push_back(7);
  destination.push_back(8);
  destination.push_back(9);

  FailingAllocator<std::uint32_t>::failNextAllocation = true;
  EXPECT_THROW(destination = source, std::bad_alloc);
  ASSERT_EQ(destination.size(), 3U);
  EXPECT_EQ(destination[0], 7U);
  EXPECT_EQ(destination[1], 8U);
  EXPECT_EQ(destination[2], 9U);

  destination = source;
  EXPECT_EQ(destination.size(), source.size());
  for (std::size_t i = 0; i < source.size(); ++i)
    EXPECT_EQ(destination[i], source[i]);
}

TEST(OperandListTest, NinthElementAllocationFailureLeavesInlinePrefixIntact) {
  TestOperandList operands;
  for (std::uint32_t value = 0; value < 8; ++value)
    operands.push_back(value + 20);

  FailingAllocator<std::uint32_t>::failNextAllocation = true;
  EXPECT_THROW(operands.push_back(28), std::bad_alloc);
  ASSERT_EQ(operands.size(), 8U);
  for (std::size_t i = 0; i < 8; ++i) EXPECT_EQ(operands[i], i + 20);

  operands.push_back(28);
  ASSERT_EQ(operands.size(), 9U);
  EXPECT_EQ(operands.back(), 28U);
  operands.clear();
  EXPECT_TRUE(operands.empty());
  operands.push_back(91);
  ASSERT_EQ(operands.size(), 1U);
  EXPECT_EQ(operands.front(), 91U);
}

TEST(OperandListTest, HasNoImplicitVectorConversionAndMeetsTargetSize) {
  static_assert(!std::is_convertible_v<zigzag::vortex::OperandList,
                                       std::vector<zigzag::CellRef>>);
  EXPECT_EQ(sizeof(zigzag::vortex::OperandList), 64U);
}

