struct TestHarness {
  ArenaManifold arena;
  VortexCore core{arena};
  VortexVM vm{core};
};

TEST(VortexCoreTest, SystemGenesisMintsAllDimensionsOffHome) {
  TestHarness h;
  EXPECT_NE(h.core.home(), noCell);
  EXPECT_EQ(h.core.arena().textOf(h.core.home()), "home");

  const auto &d = h.core.dims();
  EXPECT_NE(d.dims, noCell);
  EXPECT_NE(d.grab, noCell);
  EXPECT_NE(d.step, noCell);
  EXPECT_NE(d.spin, noCell);
  EXPECT_NE(d.stack, noCell);
  EXPECT_NE(d.contract, noCell);
  EXPECT_NE(d.clone, noCell);
  EXPECT_NE(d.cursors, noCell);
  EXPECT_NE(d.cache, noCell);
  EXPECT_NE(d.vars, noCell);
  EXPECT_NE(d.values, noCell);
  EXPECT_NE(d.pinningCursors, noCell);
  EXPECT_NE(d.name, noCell);
  EXPECT_NE(d.stdlib, noCell);

  // Each dimension is linked along d.dims
  EXPECT_EQ(h.core.arena().linked(h.core.home(), d.dims, DimVector::POS),
            d.dims);
}

TEST(VortexCoreTest, DimensionNamesRemainStableAfterHomeDirectoryIsDetached) {
  TestHarness h;
  const DimRef before    = h.core.mintDimension("d.before");
  const DimRef directory = h.core.dims().dims;
  ASSERT_TRUE(h.arena.unlink(h.core.home(), directory, DimVector::POS));
  EXPECT_EQ(h.core.findDimension("d.before"), before);

  const DimRef after = h.core.mintDimension("d.after");
  EXPECT_EQ(h.core.findDimension("d.after"), after);
  EXPECT_EQ(h.core.mintDimension("d.after"), after);
  EXPECT_EQ(h.core.findOrMintDimension("d.after"), after);
  EXPECT_EQ(h.core.findDimension("d.before"), before);
  EXPECT_FALSE(h.arena.linked(h.core.home(), directory, DimVector::POS));
}

TEST(VortexCoreTest, TruthinessKeepsItsExplicitWordsAndProseFallback) {
  EXPECT_TRUE(VortexCore::evaluateTruthiness(CellValue{std::string{"YeS"}}));
  EXPECT_TRUE(VortexCore::evaluateTruthiness(CellValue{std::string{"ON"}}));
  EXPECT_FALSE(VortexCore::evaluateTruthiness(CellValue{std::string{"Off"}}));
  EXPECT_FALSE(VortexCore::evaluateTruthiness(CellValue{std::string{}}));
  EXPECT_TRUE(
      VortexCore::evaluateTruthiness(CellValue{std::string{"a report title"}}));
}

TEST(VortexCoreTest, LinkPrimitiveLifecycle) {
  TestHarness h;
  CellRef a        = h.arena.makeCell("nodeA");
  DimRef customDim = h.core.dims().step;

  // 1. Read unlinked -> nullopt
  EXPECT_EQ(h.core.readLink(a, customDim, DimVector::POS), std::nullopt);

  // 2. Allocate (target == -1)
  auto created = h.core.allocateLink(a, customDim, DimVector::POS);
  ASSERT_TRUE(created.has_value());
  EXPECT_NE(*created, noCell);
  EXPECT_NE(*created, a);

  // 3. Read linked
  auto readRes = h.core.readLink(a, customDim, DimVector::POS);
  ASSERT_TRUE(readRes.has_value());
  EXPECT_EQ(*readRes, *created);

  // Bidirectional link check
  EXPECT_EQ(h.arena.linked(*created, customDim, DimVector::NEG), a);

  // 4. Isolate (target == 0)
  auto isolated = h.core.isolateLink(a, customDim, DimVector::POS);
  ASSERT_TRUE(isolated.has_value());
  EXPECT_EQ(*isolated, *created);

  // Now unlinked
  EXPECT_EQ(h.core.readLink(a, customDim, DimVector::POS), std::nullopt);
  EXPECT_EQ(h.arena.linked(*created, customDim, DimVector::NEG), std::nullopt);

  // 5. Literal target
  CellRef b    = h.arena.makeCell("nodeB");
  auto literal = h.core.setLink(a, customDim, DimVector::POS, b);
  ASSERT_TRUE(literal.has_value());
  EXPECT_EQ(*literal, b);
  EXPECT_EQ(h.core.readLink(a, customDim, DimVector::POS), b);
  EXPECT_EQ(h.arena.linked(b, customDim, DimVector::NEG), a);
}

TEST(VortexVMTest, LinkOutputsCarryCellIdentityIntoFollowingOperations) {
  TestHarness h;
  const CellRef first  = h.arena.makeCell("first");
  const CellRef second = h.arena.makeCell("second");
  const CellRef third  = h.arena.makeCell("third");
  ASSERT_TRUE(h.arena.link(first, h.core.dims().step, DimVector::POS, second));
  ASSERT_TRUE(h.arena.link(second, h.core.dims().step, DimVector::POS, third));

  const CellRef firstRead = h.vm.mintOpcode(OpcodeKind::Link, "#READ_FIRST");
  const CellRef firstOut  = h.arena.makeCell();
  h.core.bindInput(firstRead, first);
  h.core.bindInput(firstRead, h.arena.makeScalarCell(static_cast<std::int64_t>(
                                  h.core.dims().step)));
  h.core.bindInput(firstRead, h.arena.makeScalarCell(std::int64_t{1}));
  h.core.bindOutput(firstRead, firstOut);

  const CellRef secondRead = h.vm.mintOpcode(OpcodeKind::Link, "#READ_SECOND");
  const CellRef secondOut  = h.arena.makeCell();
  h.core.bindInput(secondRead, firstOut);
  h.core.bindInput(secondRead, h.arena.makeScalarCell(static_cast<std::int64_t>(
                                   h.core.dims().step)));
  h.core.bindInput(secondRead, h.arena.makeScalarCell(std::int64_t{1}));
  h.core.bindOutput(secondRead, secondOut);

  const CellRef halt = h.vm.mintOpcode(OpcodeKind::Halt, "#HALT");
  zigzag::expectWritten(
      h.arena.link(firstRead, h.core.dims().spin, DimVector::POS, secondRead));
  zigzag::expectWritten(
      h.arena.link(secondRead, h.core.dims().spin, DimVector::POS, halt));
  const CellRef cursor = h.vm.spawnCursor(firstRead, "identity-test");

  const auto result = h.vm.run(cursor, 10);

  ASSERT_TRUE(result.success) << result.errorMessage;
  EXPECT_EQ(h.vm.cellReferenceOf(firstOut), second);
  EXPECT_EQ(h.vm.cellReferenceOf(secondOut), third);
  EXPECT_EQ(h.arena.asInt64(firstOut), static_cast<std::int64_t>(second));
  EXPECT_EQ(h.arena.asInt64(secondOut), static_cast<std::int64_t>(third));

  const CellRef alternative = h.vm.mintOpcode(OpcodeKind::Nop, "#ALTERNATIVE");
  h.vm.pushChoicePoint(std::nullopt, alternative);
  const CellRef alternate = h.arena.makeCell("alternate");
  ASSERT_TRUE(
      h.core.setLink(first, h.core.dims().step, DimVector::POS, alternate));
  h.vm.setCursorOpcode(cursor, firstRead);
  const auto branchResult = h.vm.run(cursor, 10);
  ASSERT_TRUE(branchResult.success) << branchResult.errorMessage;
  EXPECT_EQ(h.vm.cellReferenceOf(firstOut), alternate);
  EXPECT_FALSE(h.vm.cellReferenceOf(secondOut));

  ASSERT_TRUE(h.vm.backtrack(std::nullopt));
  EXPECT_EQ(h.vm.cellReferenceOf(firstOut), second);
  EXPECT_EQ(h.vm.cellReferenceOf(secondOut), third);
  EXPECT_EQ(h.core.readLink(first, h.core.dims().step, DimVector::POS), second);

  ASSERT_TRUE(h.core.breakLink(first, h.core.dims().step, DimVector::POS));
  h.vm.setCursorOpcode(cursor, firstRead);
  const auto missingResult = h.vm.run(cursor, 10);
  ASSERT_TRUE(missingResult.success) << missingResult.errorMessage;
  EXPECT_FALSE(h.vm.cellReferenceOf(firstOut));
  EXPECT_FALSE(h.vm.cellReferenceOf(secondOut));
  EXPECT_EQ(h.arena.asInt64(firstOut), static_cast<std::int64_t>(noCell));
}

TEST(VortexVMTest, LinkMemoizationDoesNotReuseStaleTopology) {
  TestHarness h;
  const CellRef source = h.arena.makeCell("source");
  const CellRef first  = h.arena.makeCell("first");
  const CellRef second = h.arena.makeCell("second");
  ASSERT_TRUE(h.arena.link(source, h.core.dims().step, DimVector::POS, first));

  const CellRef read   = h.vm.mintOpcode(OpcodeKind::Link, "#READ");
  const CellRef output = h.arena.makeCell();
  h.core.bindInput(read, source);
  h.core.bindInput(read, h.arena.makeScalarCell(
                             static_cast<std::int64_t>(h.core.dims().step)));
  h.core.bindInput(read, h.arena.makeScalarCell(std::int64_t{1}));
  h.core.bindOutput(read, output);
  const CellRef halt = h.vm.mintOpcode(OpcodeKind::Halt, "#HALT");
  zigzag::expectWritten(
      h.arena.link(read, h.core.dims().spin, DimVector::POS, halt));
  const CellRef cursor = h.vm.spawnCursor(read, "memo-link-test");
  h.vm.enableMemoization(read, "memo:link");

  ASSERT_TRUE(h.vm.run(cursor, 10).success);
  EXPECT_EQ(h.vm.cellReferenceOf(output), first);

  ASSERT_TRUE(
      h.core.setLink(source, h.core.dims().step, DimVector::POS, second));
  h.vm.setCursorOpcode(cursor, read);
  ASSERT_TRUE(h.vm.run(cursor, 10).success);
  EXPECT_EQ(h.vm.cellReferenceOf(output), second);
}

TEST(VortexCoreTest, ValuePrimitiveReadWholeSliceAndSplice) {
  TestHarness h;
  CellRef c = h.arena.makeCell("The quick brown fox");

  // 1. Read Whole Content -> returns cell itself
  auto whole = h.core.readValue(c, 0, std::nullopt);
  ASSERT_TRUE(whole.has_value());
  EXPECT_EQ(*whole, c);
  EXPECT_EQ(h.core.render(c), CellValue(std::string("The quick brown fox")));

  // 2. Read Slice -> returns ephemeral cell quoting range
  auto slice = h.core.readValue(c, 4, 5); // "quick"
  ASSERT_TRUE(slice.has_value());
  EXPECT_NE(*slice, c);
  EXPECT_EQ(h.core.render(*slice), CellValue(std::string("quick")));

  // Negative indexing: offset -3, length 3 -> "fox"
  auto foxSlice = h.core.readValue(c, -3, 3);
  ASSERT_TRUE(foxSlice.has_value());
  EXPECT_EQ(h.core.render(*foxSlice), CellValue(std::string("fox")));

  // 3. Splice -> splices in-place on clone master, returns cell
  auto spliced = h.core.writeValue(c, 10, 5, CellValue(std::string("silver")));
  ASSERT_TRUE(spliced.has_value());
  EXPECT_EQ(*spliced, c);
  EXPECT_EQ(h.core.render(c), CellValue(std::string("The quick silver fox")));
}

