  RuntimeGuard(CellRef tokenCell, CellRef frameDescriptor,
               std::string diagnosticText,
               std::vector<std::vector<CellRef>> actuals,
               std::optional<std::uint64_t> owner,
               std::optional<CellRef> scope = std::nullopt)
