      : checkOpcode(opcode), resultSlot(result), guards(std::move(snapshot)),
        nextIndex(next), ownerActivation(owner) {}
};
using PendingGuardMap =
    detail::ReversibleCellMap<std::shared_ptr<const PendingGuardCheck>>;

