#ifndef COMMON_XANADU_VORTEX_REVERSIBLE_CELL_MAP_HPP
#define COMMON_XANADU_VORTEX_REVERSIBLE_CELL_MAP_HPP

#include <algorithm>
#include <cassert>
#include <concepts>
#include <cstddef>
#include <cstdint>
#include <expected>
#include <functional>
#include <iterator>
#include <limits>
#include <memory_resource>
#include <new>
#include <optional>
#include <stdexcept>
#include <tuple>
