class FailingResource final : public std::pmr::memory_resource {
public:
  explicit FailingResource(
      std::pmr::memory_resource *upstream = std::pmr::new_delete_resource())
      : upstream_(upstream) {}

  void failOnNextAllocation() noexcept { failAt_ = allocations_ + 1U; }

  void allowAllocations() noexcept { failAt_.reset(); }

  [[nodiscard]] std::size_t allocations() const noexcept {
    return allocations_;
  }

private:
  void *do_allocate(std::size_t bytes, std::size_t alignment) override {
    ++allocations_;
    if (failAt_ == allocations_) throw std::bad_alloc{};
    return upstream_->allocate(bytes, alignment);
  }

  void do_deallocate(void *pointer, std::size_t bytes,
                     std::size_t alignment) override {
    upstream_->deallocate(pointer, bytes, alignment);
  }

  [[nodiscard]] bool
  do_is_equal(const std::pmr::memory_resource &other) const noexcept override {
    return this == &other;
  }

  std::pmr::memory_resource *upstream_;
  std::size_t allocations_{0};
  std::optional<std::size_t> failAt_;
};

struct ConstantHash {
  [[nodiscard]] std::size_t
  operator()(const zigzag::CellRef key) const noexcept {
    (void)key;
    return 0;
  }
};

