bool insert(IntMap &map, const Cell key, const int value) {
  auto prepared = map.prepareInsert(key);
  return prepared && map.commitInsert(std::move(*prepared), int{value});
}

bool insert(RefMap &map, const Cell key, const RefValue value) {
  auto prepared = map.prepareInsert(key);
  return prepared && map.commitInsert(std::move(*prepared), RefValue{value});
}

struct Lifetime {
  explicit Lifetime(int value) : value(value) {}
  ~Lifetime() { ++destructions; }

  int value;
  inline static int destructions{0};
};

TEST(ReversibleCellMapTest, MissingUnboundAndBoundAreDifferentStates) {
  RefMap map;
  EXPECT_FALSE(map.contains(0x80000000U));
  EXPECT_EQ(map.findValue(0x80000000U), nullptr);

  ASSERT_TRUE(insert(map, 0x80000000U, std::nullopt));
  ASSERT_TRUE(map.contains(0x80000000U));
  ASSERT_NE(map.findValue(0x80000000U), nullptr);
  EXPECT_FALSE(*map.findValue(0x80000000U));

  auto erasedUnbound = std::optional<RefValue>{};
  auto preparedErase = map.prepareErase(0x80000000U);
  ASSERT_TRUE(preparedErase);
  ASSERT_TRUE(map.commitErase(std::move(*preparedErase), erasedUnbound, true));
  EXPECT_FALSE(map.contains(0x80000000U));
  std::size_t visibleEntries = 0;
  map.forEachLive([&](Cell, const RefValue &) { ++visibleEntries; });
  EXPECT_EQ(visibleEntries, 0U);
  EXPECT_TRUE(erasedUnbound.has_value());
  EXPECT_FALSE(*erasedUnbound);

  ASSERT_TRUE(map.undoErase(0x80000000U, erasedUnbound));
  ASSERT_NE(map.findValue(0x80000000U), nullptr);
  EXPECT_FALSE(*map.findValue(0x80000000U));

  auto erasedBound     = std::optional<RefValue>{};
  auto preparedReplace = map.prepareReplace(0x80000000U);
  ASSERT_TRUE(preparedReplace);
  ASSERT_TRUE(map.commitReplace(std::move(*preparedReplace), RefValue{42},
                                erasedBound));
  ASSERT_TRUE(map.findValue(0x80000000U));
  ASSERT_EQ(*map.findValue(0x80000000U), 42);
  ASSERT_TRUE(map.undoReplace(0x80000000U, erasedBound));
  ASSERT_TRUE(map.findValue(0x80000000U));
  EXPECT_FALSE(*map.findValue(0x80000000U));
}

TEST(ReversibleCellMapTest, InitialAllocationFailureCanBeRetried) {
  FailingResource resource;
  IntMap map(&resource);
  resource.failOnNextAllocation();
  auto failed = map.prepareInsert(0xf0000001U);
  ASSERT_FALSE(failed);
  EXPECT_EQ(failed.error(), ReversibleMapFailure::AllocationUnavailable);
  EXPECT_TRUE(map.empty());
  EXPECT_EQ(map.capacity(), 0U);

  resource.allowAllocations();
  ASSERT_TRUE(insert(map, 0xf0000001U, 7));
  EXPECT_EQ(*map.findValue(0xf0000001U), 7);
}

TEST(ReversibleCellMapTest, AllocationFailureLeavesLogicalMapUnchanged) {
  FailingResource resource;
  IntMap map(&resource);
  for (Cell key = 1; key <= 5; ++key) ASSERT_TRUE(insert(map, key, key * 10));
  ASSERT_EQ(map.size(), 5U);

  resource.failOnNextAllocation();
  auto failed = map.prepareInsert(6);
  ASSERT_FALSE(failed);
  EXPECT_EQ(failed.error(), ReversibleMapFailure::AllocationUnavailable);
  EXPECT_EQ(map.size(), 5U);
  for (Cell key = 1; key <= 5; ++key) {
    ASSERT_NE(map.findValue(key), nullptr);
    EXPECT_EQ(*map.findValue(key), static_cast<int>(key * 10));
  }
  EXPECT_FALSE(map.contains(6));

  resource.allowAllocations();
  ASSERT_TRUE(insert(map, 6, 60));
  EXPECT_EQ(map.size(), 6U);
}

TEST(ReversibleCellMapTest, FailedCopyAssignmentPreservesDestination) {
  FailingResource sourceResource;
  FailingResource destinationResource;
  IntMap source(&sourceResource);
  IntMap destination(&destinationResource);
  for (Cell key = 1; key <= 5; ++key) {
    ASSERT_TRUE(insert(source, key, static_cast<int>(key)));
  }
  ASSERT_TRUE(insert(destination, 99, 990));

  destinationResource.failOnNextAllocation();
  EXPECT_THROW(destination = source, std::bad_alloc);
  ASSERT_EQ(destination.size(), 1U);
  ASSERT_NE(destination.findValue(99), nullptr);
  EXPECT_EQ(*destination.findValue(99), 990);
  EXPECT_FALSE(destination.contains(1));

  destinationResource.allowAllocations();
  destination = source;
  EXPECT_TRUE(destination.logicallyEquals(source));
}

