TEST(ReversibleCellMapTest, GrowthAtMaxMinusOneRefusesBeforeRehash) {
  IntMap map;
  for (Cell key = 1; key <= 5; ++key) ASSERT_TRUE(insert(map, key, key));
  const auto capacity = map.capacity();
  ReversibleCellMapTestAccess::setGeneration(
      map, std::numeric_limits<std::uint64_t>::max() - 1U);

  auto insertion = map.prepareInsert(6);
  ASSERT_FALSE(insertion);
  EXPECT_EQ(insertion.error(), ReversibleMapFailure::CapacityOverflow);
  EXPECT_EQ(map.capacity(), capacity);
  EXPECT_EQ(map.size(), 5U);
  EXPECT_EQ(map.generationForTest(),
            std::numeric_limits<std::uint64_t>::max() - 1U);
  for (Cell key = 1; key <= 5; ++key) EXPECT_EQ(*map.findValue(key), key);
}

TEST(ReversibleCellMapTest, UndoAndReclamationProceedAtSaturatedGeneration) {
  IntMap map;
  ASSERT_TRUE(insert(map, 1, 10));

  auto insertTwo = map.prepareInsert(2);
  ASSERT_TRUE(insertTwo);
  ASSERT_TRUE(map.commitInsert(std::move(*insertTwo), 20));

  std::optional<int> erasedOne;
  auto eraseOne = map.prepareErase(1);
  ASSERT_TRUE(eraseOne);
  ASSERT_TRUE(map.commitErase(std::move(*eraseOne), erasedOne, true));

  std::optional<int> replacedTwo;
  auto replaceTwo = map.prepareReplace(2);
  ASSERT_TRUE(replaceTwo);
  ASSERT_TRUE(map.commitReplace(std::move(*replaceTwo), 30, replacedTwo));

  ReversibleCellMapTestAccess::setGeneration(
      map, std::numeric_limits<std::uint64_t>::max());
  ASSERT_TRUE(map.undoReplace(2, replacedTwo));
  ASSERT_TRUE(map.undoErase(1, erasedOne));
  ASSERT_TRUE(map.undoInsert(2));
  EXPECT_EQ(map.size(), 1U);
  EXPECT_EQ(*map.findValue(1), 10);
  EXPECT_FALSE(map.contains(2));
  map.reclaimRetainedAbsent();
  EXPECT_EQ(map.generationForTest(), std::numeric_limits<std::uint64_t>::max());
  EXPECT_EQ(map.size(), 1U);

  auto refused = map.prepareInsert(3);
  ASSERT_FALSE(refused);
  EXPECT_EQ(refused.error(), ReversibleMapFailure::CapacityOverflow);
}

struct RefCategoryVisitor {
  void operator()(Cell, const int &) & { ++lvalueCalls; }
  void operator()(Cell, const int &) && { ++rvalueCalls; }

  int lvalueCalls{0};
  int rvalueCalls{0};
};

TEST(ReversibleCellMapTest, LiveVisitorIsInvokedAsStableLvalue) {
  IntMap map;
  ASSERT_TRUE(insert(map, 1, 10));
  ASSERT_TRUE(insert(map, 2, 20));

  RefCategoryVisitor visitor;
  map.forEachLive(std::move(visitor));
  EXPECT_EQ(visitor.lvalueCalls, 2);
  EXPECT_EQ(visitor.rvalueCalls, 0);

  const IntMap &constMap = map;
  RefCategoryVisitor constVisitor;
  constMap.forEachLive(std::move(constVisitor));
  EXPECT_EQ(constVisitor.lvalueCalls, 2);
  EXPECT_EQ(constVisitor.rvalueCalls, 0);
}

TEST(ReversibleCellMapTest, NestedSameKeyInsertEraseReplaysInReverse) {
  IntMap map;
  ASSERT_TRUE(insert(map, 7, 10));

  std::optional<int> outerErase;
  auto eraseOuter = map.prepareErase(7);
  ASSERT_TRUE(eraseOuter);
  ASSERT_TRUE(map.commitErase(std::move(*eraseOuter), outerErase, true));

  ASSERT_TRUE(insert(map, 7, 20));
  std::optional<int> innerErase;
  auto eraseInner = map.prepareErase(7);
  ASSERT_TRUE(eraseInner);
  ASSERT_TRUE(map.commitErase(std::move(*eraseInner), innerErase, true));

  ASSERT_TRUE(insert(map, 7, 30));
  ASSERT_TRUE(map.undoInsert(7));
  EXPECT_FALSE(map.contains(7));
  ASSERT_TRUE(map.undoErase(7, innerErase));
  ASSERT_NE(map.findValue(7), nullptr);
  EXPECT_EQ(*map.findValue(7), 20);

  ASSERT_TRUE(map.undoInsert(7));
  EXPECT_FALSE(map.contains(7));
  ASSERT_TRUE(map.undoErase(7, outerErase));
  ASSERT_NE(map.findValue(7), nullptr);
  EXPECT_EQ(*map.findValue(7), 10);

  map.reclaimRetainedAbsent();
  EXPECT_EQ(map.size(), 1U);
}

