TEST(ReversibleCellMapTest,
     SharedValueLifetimeIsOwnedByTrailUntilRestoreOrDrop) {
  using SharedMap        = ReversibleCellMap<std::shared_ptr<Lifetime>>;
  Lifetime::destructions = 0;
  SharedMap map;
  auto prepared = map.prepareInsert(55);
  ASSERT_TRUE(prepared);
  auto first                   = std::make_shared<Lifetime>(1);
  std::weak_ptr<Lifetime> weak = first;
  ASSERT_TRUE(map.commitInsert(std::move(*prepared), std::move(first)));

  std::optional<std::shared_ptr<Lifetime>> oldValue;
  auto erase = map.prepareErase(55);
  ASSERT_TRUE(erase);
  ASSERT_TRUE(map.commitErase(std::move(*erase), oldValue, true));
  EXPECT_FALSE(map.contains(55));
  EXPECT_FALSE(weak.expired());
  ASSERT_TRUE(map.undoErase(55, oldValue));
  EXPECT_FALSE(weak.expired());

  auto eraseAgain = map.prepareErase(55);
  ASSERT_TRUE(eraseAgain);
  ASSERT_TRUE(map.commitErase(std::move(*eraseAgain), oldValue, true));
  EXPECT_FALSE(weak.expired());
  oldValue.reset();
  map.reclaimRetainedAbsent();
  EXPECT_TRUE(weak.expired());
  EXPECT_EQ(Lifetime::destructions, 1);
}

TEST(ReversibleCellMapTest, CopyMoveAndSelfAssignmentInvalidatePreparedTokens) {
  IntMap first;
  ASSERT_TRUE(insert(first, 1, 10));
  auto firstToken = first.prepareInsert(2);
  ASSERT_TRUE(firstToken);
  const auto firstGeneration = first.generationForTest();

  IntMap moved(std::move(first));
  EXPECT_GT(first.generationForTest(), firstGeneration);
  EXPECT_FALSE(moved.commitInsert(std::move(*firstToken), 20));
  EXPECT_TRUE(moved.contains(1));
  EXPECT_TRUE(first.empty());
  EXPECT_TRUE(insert(first, 9, 90));
  EXPECT_EQ(*first.findValue(9), 90);

  auto selfToken = moved.prepareInsert(2);
  ASSERT_TRUE(selfToken);
  const auto beforeSelf = moved.generationForTest();
  IntMap &sameMap       = moved;
  moved                 = sameMap;
  EXPECT_GT(moved.generationForTest(), beforeSelf);
  EXPECT_FALSE(moved.commitInsert(std::move(*selfToken), 20));

  IntMap copied;
  copied = moved;
  EXPECT_TRUE(copied.logicallyEquals(moved));
  auto sourceToken = moved.prepareInsert(3);
  ASSERT_TRUE(sourceToken);
  copied = std::move(moved);
  EXPECT_FALSE(copied.commitInsert(std::move(*sourceToken), 30));
}

