TEST(ReversibleCellMapTest, StandardMapSurfaceExposesRealPairReferences) {
  IntMap map;
  map[0] = 7;
  ASSERT_TRUE(map.insert_or_assign(0xf0000001U, 11).second);
  auto [entry, inserted] = map.emplace(22, 33);
  ASSERT_TRUE(inserted);
  EXPECT_EQ(entry->first, 22U);
  EXPECT_EQ(entry->second, 33);
  EXPECT_EQ(map.at(0), 7);
  EXPECT_EQ(map.at(0xf0000001U), 11);
  EXPECT_EQ(map.find(999), map.end());

  bool sawZero = false;
  for (auto &[key, value] : map) {
    static_assert(std::is_const_v<std::remove_reference_t<decltype(key)>>);
    if (key == 0) {
      sawZero = true;
      value   = 8;
    }
  }
  EXPECT_TRUE(sawZero);
  EXPECT_EQ(map.at(0), 8);

  std::size_t sum = 0;
  for (const auto &[key, value] : std::as_const(map)) {
    (void)key;
    sum += static_cast<std::size_t>(value);
  }
  EXPECT_EQ(sum, 52U);

  IntMap staged;
  ASSERT_TRUE(staged.insert_or_assign(44, 55).second);
  map.swap(staged);
  ASSERT_EQ(map.size(), 1U);
  EXPECT_EQ(map.at(44), 55);
  EXPECT_TRUE(staged.contains(0));
}

