}

TEST(ReversibleCellMapTest, ConvenienceEraseNeverRetainsWithoutTrailOwner) {
  ReversibleCellMap<std::shared_ptr<int>> map;
  ASSERT_TRUE(map.emplace(1, std::make_shared<int>(10)).second);
  ASSERT_EQ(ReversibleCellMapTestAccess::occupiedCount(map), 1U);
  EXPECT_EQ(map.erase(1), 1U);
  EXPECT_EQ(ReversibleCellMapTestAccess::occupiedCount(map), 0U);

  ASSERT_TRUE(map.emplace(2, std::make_shared<int>(20)).second);
  auto position = map.find(2);
  ASSERT_NE(position, map.end());
  (void)map.erase(position);
  EXPECT_EQ(ReversibleCellMapTestAccess::occupiedCount(map), 0U);
  EXPECT_TRUE(map.empty());
}

TEST(ReversibleCellMapTest, ExplicitEraseTrailOwnsPayloadUntilUndoOrDrop) {
  ReversibleCellMap<std::shared_ptr<int>> map;
  auto payload                = std::make_shared<int>(42);
  std::weak_ptr<int> lifetime = payload;
  ASSERT_TRUE(map.emplace(9, std::move(payload)).second);

  std::optional<std::shared_ptr<int>> oldValue;
  auto erase = map.prepareErase(9);
  ASSERT_TRUE(erase);
  ASSERT_TRUE(map.commitErase(std::move(*erase), oldValue, true));
  EXPECT_TRUE(map.empty());
  EXPECT_FALSE(lifetime.expired());

  ASSERT_TRUE(map.undoErase(9, oldValue));
  ASSERT_NE(map.find(9), map.end());
  EXPECT_EQ(*map.find(9)->second, 42);
  EXPECT_FALSE(oldValue);

  erase = map.prepareErase(9);
  ASSERT_TRUE(erase);
  ASSERT_TRUE(map.commitErase(std::move(*erase), oldValue, true));
  EXPECT_FALSE(lifetime.expired());
  oldValue.reset();
  EXPECT_TRUE(lifetime.expired());
}

TEST(ReversibleCellMapTest, LogicalCopyPreservesBadAllocFailureType) {
  IntMap source;
  ASSERT_TRUE(insert(source, 1, 10));
  FailingResource resource;
  resource.failOnNextAllocation();
  EXPECT_THROW((void)source.logicalCopy(&resource), std::bad_alloc);
}

TEST(ReversibleCellMapTest, ReservePreflightsExpectedInsertCapacity) {
  FailingResource resource;
  IntMap map(&resource);
  map.reserve(12);
  const auto reservedCapacity        = map.capacity();
  const auto allocationsAfterReserve = resource.allocations();
  for (Cell key = 1; key <= 12; ++key)
    ASSERT_TRUE(insert(map, key, static_cast<int>(key)));
  EXPECT_EQ(map.capacity(), reservedCapacity);
  EXPECT_EQ(resource.allocations(), allocationsAfterReserve);

  resource.failOnNextAllocation();
  EXPECT_THROW(map.reserve(1000), std::bad_alloc);
  EXPECT_EQ(map.size(), 12U);
  for (Cell key = 1; key <= 12; ++key)
    EXPECT_EQ(*map.findValue(key), static_cast<int>(key));
}

TEST(ReversibleCellSetTest, MembershipEraseAndUndoRemainLiveOnly) {
  ReversibleCellSet<> set;
  auto insertion = set.prepareInsert(0xf0000001U);
  ASSERT_TRUE(insertion);
  EXPECT_TRUE(set.commitInsert(std::move(*insertion), std::monostate{}));
  ASSERT_TRUE(set.contains(0xf0000001U));

  std::optional<std::monostate> oldMembership;
  auto erase = set.prepareErase(0xf0000001U);
  ASSERT_TRUE(erase);
  ASSERT_TRUE(set.commitErase(std::move(*erase), oldMembership, true));
  EXPECT_FALSE(set.contains(0xf0000001U));
  ASSERT_TRUE(set.undoErase(0xf0000001U, oldMembership));
  EXPECT_TRUE(set.contains(0xf0000001U));
}

TEST(ReversibleCellSetTest, KeyIterationAndEraseIfUseCellRefValues) {
  ReversibleCellSet<> set;
  EXPECT_TRUE(set.insert(0));
  EXPECT_TRUE(set.insert(0x80000001U));
  std::vector<Cell> keys;
  set.forEachKey([&](const Cell key) { keys.push_back(key); });
  ASSERT_EQ(keys.size(), 2U);
  EXPECT_TRUE((keys[0] == 0U && keys[1] == 0x80000001U) ||
              (keys[1] == 0U && keys[0] == 0x80000001U));
  EXPECT_EQ(set.eraseIfKey([](const Cell key) { return key == 0; }), 1U);
  EXPECT_FALSE(set.contains(0));
  EXPECT_TRUE(set.contains(0x80000001U));
}

TEST(ReversibleCellMapTest, CellRefHashMixesStrideKeysAcrossPowerOfTwoBuckets) {
  constexpr std::size_t bucketCount = 8192;
  constexpr std::size_t keyCount    = 4096;
  std::vector<bool> occupied(bucketCount, false);
  std::size_t maxProbe = 0;
  for (std::size_t index = 0; index < keyCount; ++index) {
    const auto key     = static_cast<Cell>(0x80000000U | (index << 12U));
    std::size_t bucket = CellRefHash{}(key) & (bucketCount - 1U);
    std::size_t probe  = 1;
    while (occupied[bucket]) {
      bucket = (bucket + 1U) & (bucketCount - 1U);
      ++probe;
    }
    occupied[bucket] = true;
    maxProbe         = std::max(maxProbe, probe);
  }
  EXPECT_LT(maxProbe, 64U);
}

TEST(ReversibleCellMapTest, ConstantHashCollisionsPreserveKeyedMapSemantics) {
  ReversibleCellMap<int, ConstantHash> map;
  for (Cell key = 0; key < 64; ++key) {
    auto [found, inserted] = map.emplace(key, static_cast<int>(key + 100U));
    ASSERT_TRUE(inserted);
    EXPECT_EQ(found->second, static_cast<int>(key + 100U));
  }
  for (Cell key = 0; key < 64; ++key)
    EXPECT_EQ(map.at(key), static_cast<int>(key + 100U));
}

